export interface StylePackMeta {
  id: string;
  name: string;
  description: string;
  order: number;
  isDefault: boolean;
}

/** 各风格包 token 覆盖（CSS 变量名 → 已解析字面值） */
export interface StylePackTokenMap {
  /** 全模式覆盖 */
  base: Record<string, string>;
  /** 仅亮色档覆盖 */
  light: Record<string, string>;
  /** 仅暗色档覆盖 */
  dark: Record<string, string>;
}

