/** 取某风格包在当前明暗档下应注入的 CSS 变量表（base 打底 + 当前档覆盖） */
export function resolveStylePackTokens(
  id: string,
  mode: 'light' | 'dark',
): Record<string, string> {
  const pack = stylePackTokens[id];
  if (!pack) return {};
  return { ...pack.base, ...pack[mode] };
}
